mapper.update:
UPDATE requirement_doc SET req_id = #{doc.reqId}, parent_id = #{doc.parentId}, category_id = #{doc.categoryId}, title = #{doc.title}, doc_type = #{doc.docType}, content = #{doc.content}, sheet_content = #{doc.sheetContent}, format = #{doc.format}, content_brief = #{doc.contentBrief}, status = #{doc.status},
visibility = #{doc.visibility}, sort_order = COALESCE(#{doc.sortOrder}, 0), owner = #{doc.owner}, owner_user_id = #{doc.ownerUserId}, updated_at = NOW() WHERE id = #{doc.id}
AND updated_at = #{oldUpdatedAt}

mapper.select:
SELECT id, workspace_id, req_id, parent_id, title, format, deleted_at
FROM requirement_doc
WHERE deleted_at IS NOT NULL AND deleted_at < #{cutoff}
ORDER BY deleted_at
LIMIT #{limit}

mapper.update:
UPDATE task SET req_doc_id = NULL, updated_at = GREATEST(NOW(), DATE_ADD(updated_at, INTERVAL 1 SECOND))
WHERE workspace_id = #{workspaceId} AND req_doc_id = #{reqDocId}
  AND (req_id IS NULL OR req_id <> #{reqId})

mapper.select:
SELECT dm.id AS id, dm.title AS title, dm.status AS status, dm.priority AS priority
FROM demand_doc_link l
INNER JOIN demand dm ON dm.id = l.demand_id AND dm.workspace_id = l.workspace_id
WHERE l.workspace_id = #{workspaceId} AND l.doc_id = #{docId}
ORDER BY dm.updated_at DESC, dm.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT workspace_id, demand_id, doc_id, created_by
FROM demand_doc_link
WHERE workspace_id = #{workspaceId}

mapper.delete:
DELETE FROM demand_doc_link
WHERE workspace_id = #{workspaceId}
  AND demand_id IN (SELECT id FROM demand WHERE workspace_id = #{workspaceId} AND req_id = #{reqId})

DELETE m FROM doc_visibility_member m
INNER JOIN requirement_doc d ON d.id = m.doc_id
WHERE m.workspace_id = #{workspaceId} AND d.req_id = #{reqId}

mapper.select:
